    count = 1
    prev_grid = current_grid
    for i in range(len(observation_history)-2, -1, -1):
        try:
            grid = _parse_grid(observation_history[i])
            if _grid_equal(grid, prev_grid):
                count += 1
                prev_grid = grid
            else:
                break
        except Exception:
            break
    return count

